using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;using System.Security.Cryptography;using System.Web.Script.Serialization;
public sealed class SettingsFile {public string Source,Relative,Hash;public long Size;public bool Selected;}
public sealed class SettingsPlan {public string Id;public List<SettingsFile> Files=new List<SettingsFile>();}
public sealed class SettingsBackup {public string Relative,Hash,Backup;public bool Existed;}
public sealed class SettingsReceipt {public string Id;public bool Restored;public List<SettingsBackup> Files=new List<SettingsBackup>();}
public static class SettingsTransfer {
 public const int MaxFile=2*1024*1024,MaxFiles=100,MaxTotal=32*1024*1024;
 static readonly string[] Extensions={".ini",".cfg",".json",".xml",".yaml",".yml",".toml",".properties",".txt",".vdf"};
 static readonly Regex Excluded=new Regex(@"(^|[\\/_.\s-])(saves?|savegames?|profiles?|progress(?:ion)?|inventory|achievements?|tokens?|auth|credentials?|login|accounts?|cookies?|cache|caches|logs?|shaders?|crash(?:es)?|consent|licenses?)([\\/_.\s-]|$)",RegexOptions.IgnoreCase);
 static readonly Regex Hint=new Regex("settings|config|options|preferences|keybind|bindings|input|graphics|video|audio|controls|display",RegexOptions.IgnoreCase);
 static readonly Regex Secrets=new Regex("(?:password|access[_-]?token|refresh[_-]?token|auth[_-]?token|session[_-]?(?:token|id)|api[_-]?key|private[_-]?key|steamid|accountid|playerid|progression|battlepass|inventory|consent)[\\\"'\\s]*[:=>]",RegexOptions.IgnoreCase);
 public static string Canonical(string path){return Path.GetFullPath(path).TrimEnd(Path.DirectorySeparatorChar);}
 public static string Within(string root,string relative){
  if(String.IsNullOrWhiteSpace(relative)||Path.IsPathRooted(relative)||relative.IndexOf(':')>=0||relative.Split('\\','/').Any(p=>p==".."||p=="."||p.Length==0||p.EndsWith(".")||p.EndsWith(" ")||p.IndexOfAny(Path.GetInvalidFileNameChars())>=0||Regex.IsMatch(p,@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\.|$)",RegexOptions.IgnoreCase)))throw new IOException("Invalid relative settings path.");
  string full=Path.GetFullPath(Path.Combine(root,relative));if(!full.StartsWith(Canonical(root)+"\\",StringComparison.OrdinalIgnoreCase))throw new IOException("Settings path leaves its selected folder.");return full;
 }
 public static void NoLinks(string path){for(string p=Path.GetFullPath(path);!String.IsNullOrEmpty(p);p=Path.GetDirectoryName(p))if((File.Exists(p)||Directory.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new IOException("Linked or redirected paths need a separate, direct folder selection.");}
 public static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
 public static bool Candidate(string relative){return !Excluded.IsMatch(relative)&&!Regex.IsMatch(Path.GetFileName(relative),@"(?:^|[_-])[0-9]{8,}(?:[_.-]|$)")&&Extensions.Contains(Path.GetExtension(relative).ToLowerInvariant())&&(Hint.IsMatch(Path.GetFileName(relative))||relative.Split('\\','/').Any(p=>p.Equals("Config",StringComparison.OrdinalIgnoreCase)));}
 public static void ValidateText(byte[] bytes){if(bytes.Length==0||bytes.Length>MaxFile)throw new IOException("Settings must be nonempty text files no larger than 2 MB.");string text;try{using(var input=new MemoryStream(bytes))using(var reader=new StreamReader(input,new UTF8Encoding(false,true),true))text=reader.ReadToEnd();}catch(DecoderFallbackException){throw new IOException("Unrecognized text encoding; binary and save formats are not imported.");}if(text.IndexOf('\0')>=0||text.Any(c=>Char.IsControl(c)&&c!='\r'&&c!='\n'&&c!='\t')||Secrets.IsMatch(text))throw new IOException("File contains binary data or account, credential, consent or progress fields.");}
 public static string Destination(string profile,string relative){
  string path=Within(profile,relative);string rel=path.Substring(Canonical(profile).Length+1);string[] roots={@"AppData\Local\",@"AppData\Roaming\",@"AppData\LocalLow\",@"Documents\",@"Saved Games\"};string prefix=roots.FirstOrDefault(r=>rel.StartsWith(r,StringComparison.OrdinalIgnoreCase));
  if(prefix==null||rel.Substring(prefix.Length).Split('\\').Length<2||!Candidate(rel.Substring(prefix.Length)))throw new IOException("Choose an app-specific settings file under AppData, Documents or Saved Games in the second Windows profile.");
  string app=rel.Substring(prefix.Length).Split('\\')[0];if(new[]{"Microsoft","Windows","Valve","Steam","Medal","Dual Steam"}.Contains(app,StringComparer.OrdinalIgnoreCase))throw new IOException("System and launcher settings are excluded from game imports.");NoLinks(path);return path;
 }
 public static void WriteAtomic(string path,byte[] bytes){Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".dualsteam-"+Guid.NewGuid().ToString("N");try{using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None))output.Write(bytes,0,bytes.Length);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
 static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=1024*1024};}
 public static string Apply(string stage,string profile,string history){
  NoLinks(stage);NoLinks(history);string planFile=Within(stage,"request.json");NoLinks(planFile);if(new FileInfo(planFile).Length>1024*1024)throw new IOException("Import request is too large.");var plan=Json().Deserialize<SettingsPlan>(File.ReadAllText(planFile));Guid id;
  if(plan==null||!Guid.TryParseExact(plan.Id,"N",out id)||Path.GetFileName(Canonical(stage))!=plan.Id||plan.Files==null||plan.Files.Count<1||plan.Files.Count>MaxFiles)throw new IOException("Invalid import request.");
  var bytes=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);int total=0;
  foreach(var file in plan.Files){string target=Destination(profile,file.Relative);if(bytes.ContainsKey(target))throw new IOException("Duplicate destination settings file.");string payload=Within(stage,"payload\\"+bytes.Count+".txt");NoLinks(payload);var info=new FileInfo(payload);if(info.Length!=file.Size||info.Length>MaxFile)throw new IOException("Import payload size changed.");byte[] data=File.ReadAllBytes(payload);ValidateText(data);if(Hash(data)!=file.Hash)throw new IOException("Import checksum changed.");total+=data.Length;if(total>MaxTotal)throw new IOException("Import exceeds 32 MB.");bytes.Add(target,data);}
  string batch=Within(history,plan.Id);if(Directory.Exists(batch))throw new IOException("This import has already been used.");Directory.CreateDirectory(batch);var receipt=new SettingsReceipt{Id=plan.Id};var originals=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);int index=0;
  int backupTotal=0;foreach(var pair in bytes){NoLinks(pair.Key);byte[] old=File.Exists(pair.Key)?ReadBounded(pair.Key):null;backupTotal+=old==null?0:old.Length;if(backupTotal>MaxTotal)throw new IOException("Existing destination settings exceed the 32 MB backup limit.");originals.Add(pair.Key,old);string backup=index+++".bak";if(old!=null)File.WriteAllBytes(Within(batch,backup),old);receipt.Files.Add(new SettingsBackup{Relative=pair.Key.Substring(Canonical(profile).Length+1),Hash=Hash(pair.Value),Backup=backup,Existed=old!=null});}
  File.WriteAllText(Within(batch,"receipt.json"),Json().Serialize(receipt));var touched=new List<string>();try{foreach(var pair in bytes){NoLinks(pair.Key);bool exists=File.Exists(pair.Key);if(exists!=(originals[pair.Key]!=null)||(exists&&Hash(ReadBounded(pair.Key))!=Hash(originals[pair.Key])))throw new IOException("A destination changed during import. Copy cancelled.");touched.Add(pair.Key);WriteAtomic(pair.Key,pair.Value);if(Hash(File.ReadAllBytes(pair.Key))!=Hash(pair.Value))throw new IOException("Copied settings verification failed.");}WriteAtomic(Within(history,"last.json"),Encoding.UTF8.GetBytes(Json().Serialize(receipt)));}catch{foreach(string path in touched){if(originals[path]!=null)WriteAtomic(path,originals[path]);else if(File.Exists(path))File.Delete(path);}throw;}
  return "Copied "+bytes.Count+" selected settings files. Originals are backed up. The scan is now cleared; scan again before another import.";
 }
 static byte[] ReadBounded(string path){var info=new FileInfo(path);if(info.Length>MaxFile)throw new IOException("An existing destination file exceeds 2 MB; import cancelled.");return File.ReadAllBytes(path);}
 public static string Restore(string profile,string history){
  NoLinks(history);string last=Within(history,"last.json");NoLinks(last);if(!File.Exists(last))throw new IOException("No settings import is available to restore.");if(new FileInfo(last).Length>1024*1024)throw new IOException("Invalid backup index.");var receipt=Json().Deserialize<SettingsReceipt>(File.ReadAllText(last));Guid id;
  if(receipt==null||!Guid.TryParseExact(receipt.Id,"N",out id)||receipt.Restored||receipt.Files==null||receipt.Files.Count<1||receipt.Files.Count>MaxFiles)throw new IOException("No unrestored import is available.");
  string batch=Within(history,receipt.Id);var changes=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);var current=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);
  foreach(var file in receipt.Files){string target=Destination(profile,file.Relative);if(changes.ContainsKey(target))throw new IOException("Duplicate backup target.");if(!File.Exists(target))throw new IOException("A copied file is missing; automatic restore stopped.");byte[] bytes=ReadBounded(target);if(Hash(bytes)!=file.Hash)throw new IOException("Settings changed after import. Restore stopped to preserve newer changes.");current.Add(target,bytes);string backup=Within(batch,file.Backup);NoLinks(backup);changes.Add(target,file.Existed?ReadBounded(backup):null);}
  var touched=new List<string>();try{foreach(var item in changes){NoLinks(item.Key);touched.Add(item.Key);if(item.Value==null)File.Delete(item.Key);else WriteAtomic(item.Key,item.Value);}receipt.Restored=true;WriteAtomic(last,Encoding.UTF8.GetBytes(Json().Serialize(receipt)));}catch{foreach(string path in touched)WriteAtomic(path,current[path]);throw;}
  return "Restored the previous settings for "+changes.Count+" files. The imported copies and backups remain recorded in the import history.";
 }
}
